export function resolveImage(
  ref: string | undefined,
): ImageSourcePropType | undefined {
  if (!ref) return undefined;
  if (ref in SIGN_IMAGES) return SIGN_IMAGES[ref];
  if (/^https?:\/\//.test(ref)) return { uri: ref };
  return undefined;
}
